//! Checks the background estimate and its subtraction against QuPath, on real
//! tissue, as one stage rather than as four.
//!
//! Fixture generated by `parity/java/BackgroundEstimate.java` via
//! `./parity/record-background.sh`, which needs a slide.
//!
//! **Why this fixture exists.** The stage is four operations — an erosion by
//! `backgroundRadius`, a mask of anything still above `maxBackground` dilated by
//! twice the radius and driven to negative infinity, a geodesic dilation back
//! under the original, and a subtraction. `RankFilterMinMax.json` pins the first
//! on 42 cases; `RegionalMaxima.json` pins the third on 24. Both on synthetic
//! input, and **nothing pins the four together on tissue**.
//!
//! That is the same gap the merge and the split had, and D-009's stage ladder
//! now points straight at it: this pipeline finds 5.8% and 7.9% more candidates
//! than QuPath *before* the intensity filter runs, and the filter then roughly
//! doubles the discrepancy — QuPath keeps 0.441 and 0.547 of its candidates
//! where this keeps 0.530 and 0.659. The filter is itself pinned on 17 recorded
//! images and passes, so what differs is what it measures. `ipToMeasure` is
//! exactly the image this fixture records.
//!
//! **Two details inside the masked branch are not pinned by these crops, and
//! are labelled rather than left reading as stronger than they are.** The branch
//! itself is: removing the `f32::NEG_INFINITY` assignment fails the test on
//! 70.93% of `sparse-a-masked`'s pixels. But narrowing the mask's dilation from
//! `radius * 2.0` to `radius * 1.5` leaves it passing, because at the limits
//! recorded here the mask saturates its crop and both radii cover the same set;
//! and turning the `>` comparison into `>=` leaves it passing, because no pixel
//! sits exactly on the limit. Pinning the radius needs a crop whose mask is a
//! *small isolated* blob, which means a limit tuned to the tissue rather than
//! one chosen to fire — worth doing, and not done here.
//!
//! **Compared by bits, not by tolerance.** A background estimate wrong in the
//! last place is a mean wrong in the last place, and a candidate sitting on the
//! threshold then falls the other way. A tolerance would hide precisely the
//! failure being looked for. Where the two differ, the failure is reported as a
//! count and a worst case rather than as the first differing pixel, because on a
//! 160x160 crop "one pixel differs" and "every pixel differs" are the same
//! assertion otherwise.

use qupath_pipeline::{Params, background_for_parity};

fn fixture() -> std::path::PathBuf {
    // Overridable so the same comparison can be pointed at a recording made at
    // a different crop size without duplicating it. A 2048x2048 recording is
    // ~200 MB and is deliberately not committed -- see the size note in
    // `parity/README.md` -- so the way to check whether this stage's agreement
    // survives production-size fields is to record one to a scratch path and
    // set this. Reusing this test rather than writing a second one is the
    // point: a re-implemented comparison would be checking the
    // re-implementation.
    if let Ok(path) = std::env::var("QUPATH_RUST_BACKGROUND_FIXTURE") {
        return std::path::PathBuf::from(path);
    }
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../parity/fixtures/BackgroundEstimate.json")
}

fn between<'a>(haystack: &'a str, start: &str, end: &str, from: usize) -> (&'a str, usize) {
    let open = haystack[from..].find(start).expect(start) + from + start.len();
    let close = haystack[open..].find(end).expect(end) + open;
    (&haystack[open..close], close)
}

fn scalar(text: &str, key: &str, from: usize) -> (f64, usize) {
    let (value, at) = between(text, &format!("\"{key}\": "), ",", from);
    (value.trim().parse().expect(key), at)
}

#[expect(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    reason = "recorded dimensions are small positive integers"
)]
fn index(value: f64) -> usize {
    value as usize
}

/// Unpacks floats recorded by their raw bits, eight hex characters each.
fn unpack(hex: &str, pixels: usize) -> Vec<f32> {
    assert_eq!(
        hex.len(),
        pixels * 8,
        "an image of {pixels} pixels should be {} hex characters, got {}",
        pixels * 8,
        hex.len(),
    );
    hex.as_bytes()
        .chunks(8)
        .map(|chunk| {
            let bits = u32::from_str_radix(std::str::from_utf8(chunk).expect("ascii"), 16)
                .expect("a hex word");
            f32::from_bits(bits)
        })
        .collect()
}

/// How two images differ: how many pixels, and the worst one.
fn compare(ours: &[f32], theirs: &[f32]) -> Option<(usize, usize, f32, f32)> {
    let mut differing = 0usize;
    let mut worst: Option<(usize, f32, f32)> = None;
    for (at, (&mine, &theirs)) in ours.iter().zip(theirs).enumerate() {
        if mine.to_bits() == theirs.to_bits() {
            continue;
        }
        differing += 1;
        let gap = (mine - theirs).abs();
        if worst.is_none_or(|(_, w_mine, w_theirs)| gap > (w_mine - w_theirs).abs()) {
            worst = Some((at, mine, theirs));
        }
    }
    worst.map(|(at, mine, theirs)| (differing, at, mine, theirs))
}

/// The whole stage reproduces QuPath's, bit for bit, on real tissue.
#[test]
fn matches_qupath_on_real_tissue() {
    let path = fixture();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record-background.sh", path.display()));

    let (radius, _) = scalar(&text, "backgroundRadius", 0);
    let (crops, _) = between(&text, "\"crops\": [", "\n  ]\n}", 0);

    let mut count = 0usize;
    let mut masked_seen = 0usize;
    let mut at = 0usize;
    while let Some(start) = crops[at..].find("{\"name\": \"") {
        let from = at + start;
        let (name, next) = between(crops, "\"name\": \"", "\"", from);
        let (width, next) = scalar(crops, "width", next);
        let (height, next) = scalar(crops, "height", next);
        let (max_background, next) = scalar(crops, "maxBackground", next);
        let (masked_text, next) = between(crops, "\"masked\": ", ",", next);
        let (input_hex, next) = between(crops, "\"input\": \"", "\"", next);
        let (subtracted_hex, next) = between(crops, "\"subtracted\": \"", "\"", next);
        at = next;

        let (width, height) = (index(width), index(height));
        let pixels = width * height;
        let masked = masked_text.trim() == "true";

        let mut ours = unpack(input_hex, pixels);
        let their_subtracted = unpack(subtracted_hex, pixels);

        let params = Params {
            background_radius: radius,
            #[expect(
                clippy::cast_possible_truncation,
                reason = "maxBackground is 2.0, exactly representable"
            )]
            max_background: max_background as f32,
            ..Params::default()
        };
        let our_mask = background_for_parity(&mut ours, width, params);

        assert_eq!(
            !our_mask.is_empty(),
            masked,
            "{name}: QuPath {} a background mask and this pipeline {}",
            if masked { "built" } else { "did not build" },
            if our_mask.is_empty() {
                "did not"
            } else {
                "did"
            },
        );
        if masked {
            masked_seen += 1;
        }

        if let Some((differing, at, mine, theirs)) = compare(&ours, &their_subtracted) {
            #[expect(
                clippy::cast_precision_loss,
                reason = "pixel counts are tens of thousands"
            )]
            let share = differing as f64 / pixels as f64 * 100.0;
            panic!(
                "{name}: the background-subtracted image differs in {differing} of \
                 {pixels} pixels ({share:.2}%); the worst is ({}, {}), which is \
                 {mine:e} here against QuPath's {theirs:e}",
                at % width,
                at / width,
            );
        }

        count += 1;
    }

    // The two guards below describe the *committed* fixture's coverage, so they
    // are asserted only for it. An override (see `fixture`) points this same
    // comparison at a recording made at another crop size, which is a different
    // question -- does the stage still agree when the field is production-sized
    // -- and has no reason to carry these seven crops. Skipping them there
    // rather than loosening them keeps the committed fixture pinned exactly as
    // it was; the pixel comparison above, which is what actually checks the
    // stage, runs either way.
    if std::env::var_os("QUPATH_RUST_BACKGROUND_FIXTURE").is_some() {
        assert!(count > 0, "the override fixture recorded no crops");
        println!("override fixture: {count} crops compared, {masked_seen} masked");
        return;
    }

    assert_eq!(count, 7, "expected 7 recorded crops");
    // The stage has two branches and the second is data-dependent. At QuPath's
    // default limit of 2.0 it fires on none of this slide's ordinary tissue —
    // D-009 found that by checking directly — so without the two crops recorded
    // at a lowered limit, every `masked` assertion above is `false == false`
    // and half the stage is unpinned. This is what caught that: the first
    // recording of this fixture had five crops, all at the default, and a crop
    // of glass added in the belief that the limit fires where the image is
    // *bright*. Optical density runs the other way.
    assert!(
        masked_seen >= 2,
        "only {masked_seen} crops reached the max_background branch; \
         at least two are recorded at a limit that should fire"
    );
}
